      "notes": "בראש ההקדמה של הפרשן: \"אמר משה בכה\"ר ברוך אלמושנינו נר\"ו ... ראשון הוא לכל בית מועד התכונה ג'ואן די שאקראבושקו ... כדור העולם ... מצאתי ראיתי לספר הזה ... העתקת אביגדור ... ולא אצא למרחב הבנת כוונת תכליתו ... ואחריו אזן ותקן גורג' פרובאג'יאו הציב ציון עיון הכוכבים ... אל ... כוונתם ירדתי לעזרת ... החכם הה\"ר אהרון עפיא נר\"ו ... קראתי הספר הזה בשם בית אל\"ים ... ושם השני שער השמים\", בסוף ההקדמה (2ב): פרוש \"ספר כדור העולם [=מראה האופנים] לג'ואן די שאקראבושקו ונקרא בשם בית אל\"ים\". || בסוף ההקדמה (2ב): פרוש \"ספר כדור העולם לג'ואן די שאקראבושקו ונקרא בשם בית אל\"ים\", החיבור בתרגומו של שלמה אביגדור מוכר בשם מראה האופנים. התרגום מתחיל במילים: \"הספר הזה נחלק לארבעה בתים\". || עם תרשימים. בדף 13א ציור בצבעים של ספינה ומגדלור.",
