      "colophon": "קולופון: \"כתבתי לעצמי ... נאם הצעיר שבצעירים חיים לוזייו (חתימה מסולסלת) ראש חדש שבט שנת והש'י'ג' לכם דיש את בציר\". בסימון השנה ייתכן שמסומנת כל המילה והשי\"ג, וגם אם כן אפשר שמניין השנים ליצירה, ואז השנה היא שי\"ט.",
      "notes": "בכה\"י: \"בית אלקים\" מאת \"משה בכה\"ר ברוך אלמושנינו\" || פרוש \"ספר כדור העולם [=מראה האופנים] לגואן די שאקרובושקו\". || בהקדמה כותב המחבר \"כונתם ירדתי בעזרת ... הה\"ר אהרן עפיא נר\"ו\". || יד מאוחרת העבירה קו על שם המחבר בכל מקום שנכתב וכתב במקומות \"אהרן\" או \"אהרן עפיא\". || בדף 1א: רשימת \"המעות הם מהקרן להוליך עמי לירושלים\". || בדף 2א רשם הבעלים: \"אמר יצחק קאריאון זה משה האיש המאסף הזה נודע בשערים שמו ומנהגו לעולם ללבוש כסות שאינו שלוא ומכנה לעצמו כל מה שמוצא מפוזר ומפורד בספרים ועתה הפליא לעשות הוסיף על השמועה במה שקרא שמו על הפי' הזה אשר באמת אינו מפרש אלא מעתיק ומאסף וזה שמו אשר יקראו לו\". ובאותה רוח כתב בדף 69א: \"הנה כל זה הוא לרדיפת הכבוד שלו ע\"כ היושר והאמת כנראה ממעשי המחבר כלם ולהיות האמת שהחכם כה\"ר אהרן עפיה יצ\"ו ביאר דבור זה מתוס' במקומו והנה המחבר שלא לישכח מנהגו לגנוב גנבו והביאו בזה\". || עם הערות אחדות בשוליים ובסוף. || נושא נוסף: מדעים. אסטרונומיה",
