      "script": "ספרדית",
      "colophon": "",
      "notes": "בראש ההקדמה של הפרשן המתייחסת לשני החיבורים, הית אלהים ושער השמיים(דף 1א): \"אמר משה בכה\"ר ברוך אלמושנינו נר\"ו ... ראשון הוא לכל בית מועד התכונה ג'ואן די שאקראבושקו ... כדור העולם ... מצאתי ראיתי לספר הזה ... העתקת אביגדור ... ולא אצא למרחב הבנת כוונת תכליתו ... ואחריו אזן ותקן גורג' פרובאג'יאו הציב ציון עיון הכוכבים ... אל ... כוונתם ירדתי לעזרת ... החכם הה\"ר אהרון עפיא נר\"ו ... קראתי הספר הזה בשם בית אל\"ים ... ושם השני שער השמים\", בסוף ההקדמה (2ב): פרוש \"ספר כדור העולם [=מראה האופנים] לג'ואן די שאקראבושקו ונקרא בשם בית אל\"ים\". || בראש החיבור: \"העתקת עיון הכוכבים המשרתים לג'ורג' פרובאג'יאו ונקרא שער השמים\" החיבור עיון הכוכבים המשרתים מתחיל במילים: \"שער עיון השמש א. השמש יש לו שלשה גלגלים\" || עם תרשימים. || קולופון המחבר: \"השבח וההודאה ... הוא יזכנו להגות בו ולעשות ספרים אין קץ ... בעזרת צור מעונים ביום א' ו' ימים לחדש תמוז שנת הש\"ו ליצירה פה שאלוניקי קרית מלך רב\".",
