      "script": "מזרחית",
      "colophon": "",
      "notes": "דף 1ב תוכן העניינים של כה\"י המקורי. רשימה של כעשרים חבורים שכבר אינם בכה\"י, רובם ככולם בענייני אסטרולוגיה וניחוש כולל כמה חבורים מיוחסים לאריסט וגם \"לחש לגיפאלו\". || כה\"י כנראה לוקט ע\"י שמואל, שמעיד על עצמו: \"אמר הכותב שמואל אחר שסדרתי לפניך כל פרטי הגורל הזה כפי אשר מצאתי כתוב מיד מורי זלה\"ה וגם ממה שקבלתי מחכמים\" (4ב). || וכן מופיע במספר מקומות נוספים: \"אמר שמואל\" (5א ועוד); \"א\"ש\" (5ב). || כולל מספר חבורים בין השאר \"סדר גורל החול\" (2א-5א), ההתחלה חסרה. ובו הוא מזכיר \"הר' אברהם אבן עזרא ז\"ל\" (2ב), \"יהודה חריזי ז\"ל\" (3א) ובתוכו: \"משפטי הגורל\" (3א), \"צורת המזלות\" (5ב-6א), ובתוכו \"סוד הגלגל\" (6א). || \"משפטי הכוכבים\" (7א-9ב) מזכיר: \"וכבר חיבר הר' אברהם זכות לוחות ... אמנם יסדם על מרחב ירושלים תוב\"ב\" (9א) וכולל מספר חבורים. || \"וזהו ספר ראשית חכמה להר' אברהם אבן עזרא ז\"ל\" (9ב-13א), לא שלם בסופו: \"אמר שמואל לא מצאתי יותר\". יש דמיון רב לכתיבת ידו של ר' שמואל ויטל. ואפשר שהוא המלקט והוא הסופר. || \"ליקוטים בענין התכונה והמשפטים היוצאים ממנה\" (13א-15א), \"לוח המעלות של כל מזל ומזל מהשנים עשר המזלות הנזכרים\" (15א-15ב), \"ענין התלי\" (15ב), \"לוחות הר\"א זכות ז\"ל\" (16א-22ב), ובראשם: \"בשלאמנקא להר\"א זכות ז\"ל\" מגיע עד לוח יא. || הלוחות של ר\"א זכות (דף 16 עד סוף כה\"י) בכתיבה אחרת, קדומה יותר; ועליהם ספרור מקורי (דף רכ\"ו) שנמחק ע\"י המלקט. || נושא נוסף: מדעים. אסטרולוגיה || נושא נוסף: מדעים. אסטרונומיה || נושא נוסף: פולקלור || נושא נוסף: אוטוגרף. ויטל, שמואל בן חיים || נושא נוסף: ביבליוגרפיה. רשימות ספרים || נושא נוסף: כתב-יד. מחיר",
