      "mms_id": "990000429850205171",
      "title": "קבץ באסטרונומיה ואסטרולוגיה : ענייני תקופות השנה, עיבור השנים, נחוש עתידות ע\"פ חישוב תקופות ומועדים וע\"פ נתונים מטאורולוגיים, גיאולוגיים אסטרולוגיים ועוד.",
