      "notes": "כה\"י נפגם ע\"י רטיבות והכתב דהה. || 1א-33א: חיבור בענייני המולדות, קביעת המועדים, עיבור השנים וחשבון תקופות השנה, נלקט ונתחבר ע\"י \"אברהם בן הר\"ס ז\"ל\", כנראה בשנת ה'רל\"ז (1477). || 1א: \"סדר ענין העבור ... אמ' אברהם המחבר ב\"ר הר\"ס ז\"ל, שאלוני קצת בחורים לכתוב אליהם ענייני העבור בדרך קצרה כאשר עשו לפנים ... בענייני הלכות שחיטה ... ועניתי להם לא ראי זה כראי זה ... ענייני העבור הם דברים עמוקים ...\". || 21א: \"... יש בידינו רס\"ג מחזורים וג' שנים מהחמשת אלפים שנה שעברו ... י\"ב מחזורים וט' שנים מהר'ל'ז' שנים שיש לנו יתירים על החמשת אלפים ...\" משמע שנתחבר בשנת ה'רל\"ז. || 32ב: \"דע כי הגויים עושין ראש השנה שלהם בקלינדרי דיינרו ... יום מהילות ישו ... וזה לך האות נפל\"ך חזו\"ז לעולם לא יזוז ... קלינדרי אברילי ... קלינדרי יולייו ... קלינדרי אוטוברו ...\" (שמות החודשים כאן ולהלן בדף 81ב, 108א - כולם באיטלקית). || 33ב-125א: \"חיבור לדעת המשכת המולדות והמועדים והוראות תקופות והרבה עניינים אחרים אשר תמצאם מסודרים בעשרים פרקים אשר נכתב לפנינו בעה\"ו\". || 61א-62א: לוחות למחזורים רעג-רפד (שנים ה'קס\"ט-ה'שנ\"ט), נתחבר כנראה בסוף שנת ה'קס\"ח (1408). || 64א: \"בערב ראש השנה שהוא ביום ו' כ\"ט אלול משכימין לעמוד לסליחות ... ואומ' פתיחה יי' אלהי הצבאות נורא בעליונים ...\" תאריך זה מתאים לראש-השנה תס\"ט (כ\"ט אלול תס\"ח) שבה מתחילים לוחות המחזורים דלעיל. || הסליחה \"ה' אלהי הצבאות\" (דוידזון, אוצר, א 686) שאינה נפוצה ברוב סדרי הסליחות של האשכנזים, היתה נפוצה כנראה בקרב האשכנזים שבאיטליה, ונדפסה ב\"סליחות מכל השנה\" מנהג אשכנז, ויניציאה ש\"ח. || 81ב: \"... אבריל ... מאייו ... גונייו ... גולייו ... אגושטו ... אויטוברו ... נובינברו ... דגיזינברו ... גאניירו ... פיבירירו ...\". || 92ב-107ב: \"סידרא דסיהרא על ענייני המלאכות ומשא ומתן ושותפות, ועניין תולדות וחלאים ורעמים ועניין החל[ו]מות על מה מורים על פי הימים\". || 108א: \"אלין אינו יומייא שבעתא דאתקין עזרא כהנא רבא על פי התכונה. אם יבא קלינדי יינארו בא' בשבת החורף יהיה טוב ... והמטר ... והקיץ ... והבהמות ... והאביב ... והקיץ ... זרע ... והבקעה ... והצאן והשמן והדבש ... בציר ... ויין ... ובתינוקות מות ...\". || 125ב-134א: \"ספר בלעי [לניחוש העתידות ע\"פ תופעות בטבע] והוא עשרה פרקים ... לכוכבים ... לריח ... לרעמים ... לגשמים ... לקשת ... לברד ...\". || 134א-138א: \"סדר רעשים ורעמים\" ו\"סימני הירח כשהוא לוקה\" לפי החודשים והימים שבהם. || 138ב-139א: \"נוסח אחר מעניין לקות הלבנה כמו בפרק ג' למעלה בספר בלעי\". || 139ב-140א: \"ואלו הן תולדות הרעמים מז' כוכבי לכת ומי\"ב מזלות\". || 140ב-146ב: \"סדר תקופות\" - ניחוש העתידות לפי שעות תחילת התקופות: \"תקופת ניסן, אם תבא בראשית הלילה, תהיה אותה שנה שנת חיים ... ואם תבוא בחצי הלילה ... תקופת תמוז ...\". || 146ב-163א: חיבור באסטרונומיה ואסטרולוגיה, על מזלות החודשים והשפעותיהם על הבריאה והאדם. פותח: \"מחלוקת כל השנה י\"ב חדשים לד' תקופות ג' חודשים ... ועל זה חלקו חכמי התכונה סגולות המזלות ... לי\"ב חלקים ...\". || 148ב-150א: \"ספר רפפות; בזמן שמזדעזע אחד מן האברים של אדם או ידלג, וירצה לידע על איזה עניין טוב או רע הוא יורה ...\" || 151א-157ב: \"כח שנים עשר מזלות\"; חיבור תיאורטי באסטרולוגיה, על טבעם, קשריהם עם ארבעת היסודות ומינם של המזלות (זכר או נקבה). || 164א: תרשים אסטרונומי, דהה לגמרי מפגיעת רטיבות. || 165א-216ב: חיבור מלוקט באסטרולוגיה, מכיל \"משפטי הנולדים\", פותח: נתתי אל לבי לשמוע להבין בספרים אשר עשיתי הספר הזה כפי כחי ערכתי שיחי, פירשתי הנה י\"ב מזלות ... ומשפטי הנולדים על בירור ...\". || 192ב-193א: כלל באסטרולוגיה. בסופו: \"נשלם הכלל אשר חבר הרב המובהק אדוני זקני ר' פנחס הקצין זצוק\"ל\". || 203ב-204א: \"סוד חשבון בעלי מלחמה והנצוח, אשר שלח הפילוסוף הגדול ארסטו למלך אליסנדרו (ניצחון ע\"י עימות מאגי של חשבון אותיות שמו של הלוחם כנגד זה של אויבו). || 205א-206א: \"סימן למנוצחים\", למאבק ע\"י צירוף של עימות אותיות שמות הנאבקים עם אסטרולוגיה, על פי גלגל [אשפירא, SPEHERA] של אותיות. || 205א: \"זה הפתרון האשפירא דאלפוניאה הפילוסוף\".- 206א: \"וזו היא האשפירא מאפולוניאה\" (כותרת לציור הגלגל ומעליו הכותרת: \"וזו היא האשפירא מאנפולולוניאה\". || 217ב-228ב: \"ספר השאלות לגואן גיל\" באסטרולוגיה, מסודר ע\"פ י\"ב הבתים. מסתמך על החכמים בטלמיוס [פתולמיוס], עלי, אלמנצור, אלטברי. פותח: \"הבית הראשון. הרוצה לדעת ... חייו כאשר יקרה לו מטוב ורע ... ישאל שאלו על זה ראשונה ...\".- || החיבור מבוסס כנראה על \"השאלות\" למאשאללה (כ\"י קמברידג' 481, ס' 16778 במכון לתכ\"י), אך אינו זהה עמו. || \"גואן גיל\" הוא חכם ספרדי \"גואן גיל די בורגוש\" הנודע רק ע\"פ חיבורו באסטרולוגיה ומאגיה, המועתק בפורטוגלית בכתב עברי, כ\"י בודלי 282 (ס' 19352 במכון לתכ\"י), שהדעות חלוקות האם הוא אכן המחבר או רק \"מעתיק קודם\". || 207א-213א: חיבורי כוכבי לכת במזלות. בסוף: \"נשלמו חיבורי הכוכבים, נעתקו מהנוצרים\". || 213א-216ב: \"זהו ספר הגורלות שחיבר הפילוסוף הגדול כמהר\"ר אברהם אבן עזרא ז\"ל\". || נושא נוסף: מדעים. אסטרונומיה || נושא נוסף: מדעים. אסטרונומיה. עברונות || נושא נוסף: מדעים. מטאורולוגיה || נושא נוסף: מדעים. אסטרולוגיה || נושא נוסף: פולקלור. גורלות",
