      "notes": "בשער כה\"י: \"ספר ראשית החכמה להחכם ר' אברהם ן' עזרא הספרדי, כולל עשרה ספרים ... הועתק מכתיבת יד ישן ספרדית, בשנת תקפ\"ט לפ\"ק\" [ברם חיבורו של ראב\"ע 'ראשית החכמה' עצמו אינו כלול בין הספרים המועתקים כאן!]. || 1-:17 כלי האצטרלאב לאבן אלצפאר בתרגום יעקב בן מכיר.- 19-:35 אגרת המספקת \"בליחויות ובמטר ... עשאה ... לחביב מתלמידיו יעקב ן' אסחק אלכנדי\" בתרגום קלונימוס בן קלונימוס.- 36-:43 אגרת אחרת ליעקב בן אסחק אלכנדי \"בסבות עליונות, באישים העליונים, המורות על הוויות המטר\". גם היא בתרגום קלונימוס בן קלונימוס- 45-:48 צורת שנים עשר מזלות.- 49-:52 צורת שבעה כוכבי לכת.- 55-:75 כלי הנחושת.- 77-:85 העולם (בעניני מחברות המשרתים).-87-:104 הטעמים (טעמי חכמת הגלגל).- 105-:111 המבחרים (הימים הטובים והרעים לתחלת כל מעשה).- 114-:138 \"מולד האדם\" (=ספר המולדות). || זהה לכתב-יד ירושלים - הספרייה הלאומית 8°3573 Ms. Heb. ויתכן שהועתק ממנו. || נושא נוסף: מדעים. אסטרונומיה || נושא נוסף: מדעים. אסטרולוגיה",
