      "script": "אשכנזית",
      "colophon": "",
      "notes": "א] 1א-12ב: חיבור בתכונה למחבר מאוחר, אשכנזי (לפי סגנון כתיבתו), יודע על תמונת העולם הקופרניקאית ההליוצנטרית (3א) אך טורח להפריכה. מגמת החיבור - הרמוניזציה של ידיעות מדעיות עם פרשנות המקרא היהודית. || נפסק לפני סוף החיבור. || מתחיל: \"השער הראשון מתכונת כדור הארץ; פרק ראשון: מהראיות הברורות היות הארץ כדורית ולא שטחיית כדעת רבים ...\". || הפרק השני, היות הארץ מקופה[!] מהמים ויחדיו יעמדו והיו לכדור עגול אחד והמים בתוך הארץ, ולא כדעת רבים היות הארץ בתוך המים כתפוח. עיין מכל זה בספר חסד לאברהם [לר\"א אזולאי, מעין ב, נהר א-ג] כי השתבש מאוד ...\". || ב] (1) 13א-20ב: \"פירוש הכדור\", הדרכה לשימוש במכשיר \"אשפירא\" והוא גלובוס עתיק המתאר את הארץ והגלגלים המקיפים אותה. אין זה החיבור \"תכונת הכדור\" או \"תמונת הכדור\" שבכ\"י ברלין 112 והמבורג 291. || ניכר בו שימוש ב\"פירוש על מעשה הכדור\" הנדפס עם ס' צורת הארץ לר' אברהם בר חייא הנשיא, אופיבאך ת\"פ, וס' נחמד ונעים לר' דוד גנז, שער ב (יעסניץ תק\"ג). || מכיל ו' פרקים. מתחיל: \"דע כי הכדור יקרא כל דבר עגול ... ועתה נדבר בכדור אשר שמו אשפירא ובעגולים אשר בו מבית ומחוץ ...\". מסתיים: \"... יתגלה אור הלבנה ... ושבה אל בית אביה כנעוריה\". || (2) 22א-31ב: \"פירוש החבור\" מאת מרדכי בן אליעזר(?) והוא ביאור על הקדמת התוכן עמנואל בן יעקב ללוחות \"שש כנפים\" שלו (ראה כ\"י 8/1759). מביא ציטוטים ממנה ואחריהן ביאוריו שפתיחתם 'ר\"ל' (רצונו לומר). || בסוף בא הציון: \"זה הפירוש שלי אני מרדכי בן אליעזר\" בכתיבת ידו של כותב כל החלק הב' של כה\"י הנוכחי. || ומסתבר כי הכותב הוא המחבר (ושאין זה ביאור על \"שש כנפים\" שעשה מרדכי בן אליעזר כומטייאנו, 1466-1480, הנז' אצל גורלנד, גנזי ישראל בסט. פיטרבורג, חוב' ג, עמ' 103). || לפני החיבור (21א) שער ובו ייחוס מוטעה של ס' \"שש כנפים\" ל\"שלמה תלמיד\", מובא בס' שפתי ישנים לר' שבתי בס. || נושא נוסף: מדעים. אסטרונומיה || כתיבות שונות.",
      "subjects": "Astronomy -- Early works to 1800",
