      "notes": "עם הקדמת המתרגם אפרים מזרחי וגם הקדמתם של המפרשים \"חיים בן ... צעיר הנקרא ... ר' חיים ליסקר ו\"הרמ\"א\" [=משה איסרליש] עם פירושיהם של חיים ליסקר, הרמ\"א, וכן של מתתיה \"דלקראט\" בשוליים. || המעתיק של חבורו של פירבך הוא \"אברהם בן לא\"א יצחק ז\"ל ממדינת מעהרין\"; אולם הפירוש בשוליים הוא בהעתקתו של חיים ליסקר עצמו; || וכן אנו קוראים בדף 120א: \"תם ונשלם בעזר השם הי' יום ד' תשעה ימי' בחדש ניסן בפרט השקפה ממעון קדשך מן השמי\"ם ופ\"ק חיים נק' ליסקר\" והיא שנת השצ\"ה [=1635]. || נושא נוסף: מדעים. אסטרונומיה",
