      "century": "16th Century (1501–1600)",
      "year": null,
      "extent": "129 דף.",
      "script": "איטלקית",
      "colophon": "",
      "notes": "ספרו של פורבך עם פירוש מקיף לפי השערתו של משה שטיינשניידר, מחבר הפרוש הוא מתתיהו דלקרוט. לא מצאתי שום סימוכין לזיהוי זה ואולם נראה שההערות שבכה\"י (ראה למשל דף 127א) בכתיבה זהה להערות שבכ\"י אוקספורד-בודלי 1640 שהוא אוטוגרף של דלקרט. || לכן מסתבר מאד שכה\"י שלנו היה ברשותו של מתתיה דלקרוט והוא העיר בשולי הדפים. || בדף 69א: \"ובזמננו שי\"א לפ\"ק ...\". מכאן שהפרוש (או חלק זה ממנו) נכתב בשנת 1551. שים לב שהמלה \"ובזמננו\" נכתבה מעל למחק. בדף 107ב: \"אמר לי הנוצרי אשר למדני בזאת החכמה\". || בסופו הערה מאת מלמד אחד: \"נכנסתי בבית כמה\"ר עמינדב פאנו יצ\"ו ללמד בני בניו יצ\"ו\" ורשימות קבלות בשנים של\"ז-של\"ח. עמינדב מפאנו הוא כנראה הבנקאי ממנטובה (ראה: סימונסון, מנטובה, מפתח). || נושא נוסף: מדעים. אסטרונומיה || נושא נוסף: צנזורה 1599 || נושא נוסף: צנזורה 1628 || נושא נוסף: מלמד",
