      "script": "איטלקית | אשכנזית",
      "colophon": "",
      "notes": "בכה\"י: מאת \"חיים בכמ\"ר שלמה הכהן יצ\"ו\" || דרושים אחדים על דרך הקבלה או הפילוסופיה. || חתימת המחבר מובאת בשני מקומות (79א, 103ב). מזכיר \"מהר\"ר ישעיה ממונטייאנא יצ\"ו\" (72ב). ראה כ\"י בודפשט קאופמן 146. || בין הדרשות דף ריק. הדף הריק 80ב רשום עליו הפלינדרום המיוחס לראב\"ע \"ידעו מאביכם כי לא בוש\" וכו'. || דף 92א: \"ובזה אמר דודי יצחק הכהן נ\"ע בפירושו למסכת אבות הנקרא בספריו יצחק הכהן בן חיים הכהן נ\"ע\" ובדף 2: \"עכ\"ל דודי יצחק הכהן נ\"ע בן זקיני חיים הכהן נ\"ע\". || פירושו של זה האחרון למסכת אבות מצוי בכ\"י לונדון-הספריה הבריטית 26960 ADD. (מרגליות 230 ס' 5696), דף 64א-188ב. והושלם ברומה בשנת רע\"ח. ציטוט נוסף מפרוש למסכת אבות לר' יצחק בן חיים הכהן - דוד המחבר מובא בדף 129ב. || בדף 103ב: דברי התנצלות המחבר: \"יען הפצרתני להעלו' על ספר תורותי והלולי הוריתי בהם באגפי ק\"ק קסאלי ... אבל בהיות כי מעולם לא עברתי על דעת חבירי ואני אמרתי להפ\"ק זממיך ולהאות לך ... זעירא דמן חבריא חיים בכמ\"ר שלמה הכהן יצ\"ו\". || ייתכן שהדפים נכרכו שלא כסדרם. || דף 108ב: \"גם מן קטן וגדול מקהל קזאל ובראשם שלמה דילאקרוט\". כנראה שלמה בן מתתיה דלקרוט. || דף 115א-121א: דרשה על \"תודה לה' לרצונכם תזבחו\". || דף 125א-137ב: דרשה על \"מזבח אדמה תעשה\". מצטט \"מצטט \"גאון הדור ר' שלמה\" (127ב) || דף 139א \"מאמרים לנישואין\" לקט מאמרי חז\"ל. || דף 139א-142א: דרשה לברית מילה לר' שלמה. מתחיל \"זאת הדרשה דרש מהר\"ר שלמה בברית מילת בנו יהודה יצ\"ו\". || דף 144א- לקט מאמרי חז\"ל, תחת הכותרת \"מאמרי התלמוד נקובים בשמותם איש על דגלו באותות\". || נושא נוסף: נשואין || נושא נוסף: דרשות || נושא נוסף: ברית מילה",
